    ///
    /// Changes to the returned values do not update this object. Modify the copies,
    /// then assign the array back to `checks`.
    #[wasm_bindgen(getter)]
    pub fn checks(&self) -> Vec<WasmDoctorCheck> {
        self.checks.clone()
    }

    /// Takes ownership of every element in `checks`.
    /// wasm-bindgen cannot borrow class values nested in an array; copy each retained
    /// element with `copyForTransfer()` before passing the array.
    #[wasm_bindgen(setter)]
    pub fn set_checks(&mut self, value: Vec<WasmDoctorCheck>) {
        self.checks = value;
    }

    /// Whether no check failed. Warnings and skips do not count as failures,
    /// so the report stays usable as a scripting/CI gate.
