/// Configuration for document chunking and analysis heuristics.
///
/// Every threshold is a public field so callers can override any subset via
/// struct-update syntax: `HeuristicsConfig { text_layer_threshold: 0.5, ..Default.default() }`.
#[derive(Clone)]
#[wasm_bindgen]
pub struct WasmHeuristicsConfig {
    enable_pdf_text_heuristics: bool,
    text_layer_threshold: f32,
    file_size_threshold_bytes: u64,
    page_count_threshold: u32,
    target_pages_per_chunk: u32,
    max_pages_per_chunk: u32,
    disk_processing_threshold_bytes: u64,
    min_chars_per_page: u32,
    max_xlsx_sheet_count: u32,
    max_xlsx_workbook_cells: u64,
    max_pptx_embedded_count: u32,
}

impl Default for WasmHeuristicsConfig {
    fn default() -> Self {
        <xberg::HeuristicsConfig as Default>::default().into()
    }
}

#[wasm_bindgen]
impl WasmHeuristicsConfig {
    #[allow(clippy::too_many_arguments)]
    #[allow(non_snake_case)]
    #[wasm_bindgen(constructor)]
    pub fn new(
        enablePdfTextHeuristics: Option<bool>,
        textLayerThreshold: Option<f32>,
        fileSizeThresholdBytes: Option<u64>,
        pageCountThreshold: Option<u32>,
        targetPagesPerChunk: Option<u32>,
        maxPagesPerChunk: Option<u32>,
        diskProcessingThresholdBytes: Option<u64>,
        minCharsPerPage: Option<u32>,
        maxXlsxSheetCount: Option<u32>,
        maxXlsxWorkbookCells: Option<u64>,
        maxPptxEmbeddedCount: Option<u32>,
    ) -> WasmHeuristicsConfig {
        WasmHeuristicsConfig {
            enable_pdf_text_heuristics: enablePdfTextHeuristics.unwrap_or(true),
            text_layer_threshold: textLayerThreshold.unwrap_or(0.7),
            file_size_threshold_bytes: fileSizeThresholdBytes.unwrap_or(10485760),
            page_count_threshold: pageCountThreshold.unwrap_or(50),
            target_pages_per_chunk: targetPagesPerChunk.unwrap_or(10),
            max_pages_per_chunk: maxPagesPerChunk.unwrap_or(25),
            disk_processing_threshold_bytes: diskProcessingThresholdBytes.unwrap_or(52428800),
            min_chars_per_page: minCharsPerPage.unwrap_or(50),
            max_xlsx_sheet_count: maxXlsxSheetCount.unwrap_or(200),
            max_xlsx_workbook_cells: maxXlsxWorkbookCells.unwrap_or(5000000),
            max_pptx_embedded_count: maxPptxEmbeddedCount.unwrap_or(50),
        }
    }

    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmHeuristicsConfig {
        self.clone()
    }

    #[wasm_bindgen(getter, js_name = "enablePdfTextHeuristics")]
    pub fn enable_pdf_text_heuristics(&self) -> bool {
        self.enable_pdf_text_heuristics
    }

    #[wasm_bindgen(setter, js_name = "enablePdfTextHeuristics")]
    pub fn set_enable_pdf_text_heuristics(&mut self, value: bool) {
        self.enable_pdf_text_heuristics = value;
    }

    #[wasm_bindgen(getter, js_name = "textLayerThreshold")]
    pub fn text_layer_threshold(&self) -> f32 {
        self.text_layer_threshold
    }

    #[wasm_bindgen(setter, js_name = "textLayerThreshold")]
    pub fn set_text_layer_threshold(&mut self, value: f32) {
        self.text_layer_threshold = value;
    }

    #[wasm_bindgen(getter, js_name = "fileSizeThresholdBytes")]
    pub fn file_size_threshold_bytes(&self) -> u64 {
        self.file_size_threshold_bytes
    }

    #[wasm_bindgen(setter, js_name = "fileSizeThresholdBytes")]
    pub fn set_file_size_threshold_bytes(&mut self, value: u64) {
        self.file_size_threshold_bytes = value;
    }

    #[wasm_bindgen(getter, js_name = "pageCountThreshold")]
    pub fn page_count_threshold(&self) -> u32 {
        self.page_count_threshold
    }

    #[wasm_bindgen(setter, js_name = "pageCountThreshold")]
    pub fn set_page_count_threshold(&mut self, value: u32) {
        self.page_count_threshold = value;
    }

    #[wasm_bindgen(getter, js_name = "targetPagesPerChunk")]
    pub fn target_pages_per_chunk(&self) -> u32 {
        self.target_pages_per_chunk
    }

    #[wasm_bindgen(setter, js_name = "targetPagesPerChunk")]
    pub fn set_target_pages_per_chunk(&mut self, value: u32) {
        self.target_pages_per_chunk = value;
    }

    #[wasm_bindgen(getter, js_name = "maxPagesPerChunk")]
    pub fn max_pages_per_chunk(&self) -> u32 {
        self.max_pages_per_chunk
    }

    #[wasm_bindgen(setter, js_name = "maxPagesPerChunk")]
    pub fn set_max_pages_per_chunk(&mut self, value: u32) {
        self.max_pages_per_chunk = value;
    }

    #[wasm_bindgen(getter, js_name = "diskProcessingThresholdBytes")]
    pub fn disk_processing_threshold_bytes(&self) -> u64 {
        self.disk_processing_threshold_bytes
    }

    #[wasm_bindgen(setter, js_name = "diskProcessingThresholdBytes")]
    pub fn set_disk_processing_threshold_bytes(&mut self, value: u64) {
        self.disk_processing_threshold_bytes = value;
    }

    #[wasm_bindgen(getter, js_name = "minCharsPerPage")]
    pub fn min_chars_per_page(&self) -> u32 {
        self.min_chars_per_page
    }

    #[wasm_bindgen(setter, js_name = "minCharsPerPage")]
    pub fn set_min_chars_per_page(&mut self, value: u32) {
        self.min_chars_per_page = value;
    }

    #[wasm_bindgen(getter, js_name = "maxXlsxSheetCount")]
    pub fn max_xlsx_sheet_count(&self) -> u32 {
        self.max_xlsx_sheet_count
    }

    #[wasm_bindgen(setter, js_name = "maxXlsxSheetCount")]
    pub fn set_max_xlsx_sheet_count(&mut self, value: u32) {
        self.max_xlsx_sheet_count = value;
    }

    #[wasm_bindgen(getter, js_name = "maxXlsxWorkbookCells")]
    pub fn max_xlsx_workbook_cells(&self) -> u64 {
        self.max_xlsx_workbook_cells
    }

    #[wasm_bindgen(setter, js_name = "maxXlsxWorkbookCells")]
    pub fn set_max_xlsx_workbook_cells(&mut self, value: u64) {
        self.max_xlsx_workbook_cells = value;
    }

    #[wasm_bindgen(getter, js_name = "maxPptxEmbeddedCount")]
    pub fn max_pptx_embedded_count(&self) -> u32 {
        self.max_pptx_embedded_count
    }

    #[wasm_bindgen(setter, js_name = "maxPptxEmbeddedCount")]
    pub fn set_max_pptx_embedded_count(&mut self, value: u32) {
        self.max_pptx_embedded_count = value;
    }

    #[allow(clippy::should_implement_trait)]
    #[wasm_bindgen]
    pub fn default() -> WasmHeuristicsConfig {
        xberg::HeuristicsConfig::default().into()
    }

    /// Validate the configuration.
    ///
    /// # Errors
    ///
    /// Returns `HeuristicsError.ConfigError` when:
    /// - `target_pages_per_chunk` is 0
    /// - `max_pages_per_chunk` < `target_pages_per_chunk`
    /// - `file_size_threshold_bytes` is 0
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen]
    pub fn validate(&self) -> Result<(), JsValue> {
        let result = xberg::HeuristicsConfig::from(self.clone())
            .validate()
            .map_err(|e| JsValue::from_str(&e.to_string()))?;
        Ok(result)
    }
}

