/// Configuration for an LLM provider/model via liter-llm.
///
/// Each feature (VLM OCR, VLM embeddings, structured extraction) carries
/// its own `LlmConfig`, allowing different providers per feature.
///
/// # Example
///
/// ```toml
/// [structured_extraction.llm]
/// model = "openai/gpt-4o"
/// api_key = "sk-..."  # or use XBERG_LLM_API_KEY env var
/// ```
///
/// `Debug` is implemented by hand so `api_key`, header values, and the AWS
/// credentials in `BedrockConfig` are never printed.
#[derive(Clone)]
#[wasm_bindgen]
pub struct WasmLlmConfig {
    model: String,
    api_key: Option<String>,
    base_url: Option<String>,
    timeout_secs: Option<u64>,
    max_retries: Option<u32>,
    temperature: Option<f64>,
    max_tokens: Option<u64>,
    top_p: Option<f64>,
    stop: Option<Vec<String>>,
    seed: Option<i64>,
    presence_penalty: Option<f64>,
    frequency_penalty: Option<f64>,
    reasoning_effort: Option<String>,
    extra_body: Option<JsValue>,
    load_env: Option<bool>,
    headers: Option<JsValue>,
    providers: Option<Vec<WasmLlmProviderConfig>>,
    cache: Option<WasmLlmCacheConfig>,
    budget: Option<WasmLlmBudgetConfig>,
    rate_limit: Option<WasmLlmRateLimitConfig>,
    cost_tracking: Option<bool>,
    tracing: Option<bool>,
    cooldown_secs: Option<u64>,
    health_check_secs: Option<u64>,
    bedrock: Option<WasmBedrockConfig>,
    credential_provider: Option<JsValue>,
    max_concurrency: Option<usize>,
    max_response_bytes: Option<usize>,
}

impl Default for WasmLlmConfig {
    fn default() -> Self {
        <xberg::LlmConfig as Default>::default().into()
    }
}

