/// A ColBERT multi-vector embedding: one row per attention-live token.
///
/// `data` is a flat, row-major buffer of length `num_tokens * dim` — row `i`
/// (the embedding for token `i`) occupies `data[i*dim .. (i+1)*dim]`. Flat
/// storage keeps the type FFI-friendly across binding boundaries; use
/// `MultiVectorEmbedding.rows` internally to iterate per-token slices.
#[derive(Clone, Default)]
#[wasm_bindgen]
pub struct WasmMultiVectorEmbedding {
    num_tokens: u32,
    dim: u32,
    data: Vec<f32>,
}

#[wasm_bindgen]
impl WasmMultiVectorEmbedding {
    #[allow(non_snake_case)]
    #[wasm_bindgen(constructor)]
    pub fn new(numTokens: u32, dim: u32, data: Vec<f32>) -> WasmMultiVectorEmbedding {
        WasmMultiVectorEmbedding {
            num_tokens: numTokens,
            dim,
            data,
        }
    }

    #[wasm_bindgen]
    #[allow(clippy::should_implement_trait)]
    pub fn default() -> WasmMultiVectorEmbedding {
        <WasmMultiVectorEmbedding as ::core::default::Default>::default()
    }

    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmMultiVectorEmbedding {
        self.clone()
    }

    #[wasm_bindgen(getter, js_name = "numTokens")]
    pub fn num_tokens(&self) -> u32 {
        self.num_tokens
    }

    #[wasm_bindgen(setter, js_name = "numTokens")]
    pub fn set_num_tokens(&mut self, value: u32) {
        self.num_tokens = value;
    }

    #[wasm_bindgen(getter)]
    pub fn dim(&self) -> u32 {
        self.dim
    }

    #[wasm_bindgen(setter)]
    pub fn set_dim(&mut self, value: u32) {
        self.dim = value;
    }

    #[wasm_bindgen(getter)]
    pub fn data(&self) -> Vec<f32> {
        self.data.clone()
    }

    #[wasm_bindgen(setter)]
    pub fn set_data(&mut self, value: Vec<f32>) {
        self.data = value;
    }

    /// Returns `true` if `data` holds exactly `num_tokens * dim` values — i.e.
    /// the flat buffer matches the declared shape.
    ///
    /// All fields are `pub` and the type is `Deserialize`, so a value coming
    /// from an untrusted source (FFI caller, JSON, a store row) may be
    /// malformed. `max_sim_score` guards on this so a length-mismatched
    /// buffer scores `0.0` rather than silently mis-scoring (a shorter `data`
    /// would make `rows`' `chunks_exact` drop a trailing partial
    /// chunk). Uses `checked_mul` so an overflowing `num_tokens * dim` is
    /// reported as malformed instead of wrapping.
    #[wasm_bindgen(js_name = "isWellFormed")]
    pub fn is_well_formed(&self) -> bool {
        xberg::MultiVectorEmbedding::from(self.clone()).is_well_formed()
    }
}

