/// Multi-backend OCR pipeline with quality-based fallback.
///
/// Backends are tried in priority order (highest first). After each backend
/// produces output, quality is evaluated. If it meets `quality_thresholds.pipeline_min_quality`,
/// the result is accepted. Otherwise the next backend is tried; if none clears the
/// threshold, an internal selection policy derived from the `OcrConfig` decides which
/// stage's result is returned as the best effort (`vlm_fallback` pipelines prefer their
/// last non-empty stage; explicit and classical pipelines stay score-based).
#[derive(Clone, Default)]
#[wasm_bindgen]
pub struct WasmOcrPipelineConfig {
    stages: Vec<WasmOcrPipelineStage>,
    quality_thresholds: WasmOcrQualityThresholds,
}

#[wasm_bindgen]
impl WasmOcrPipelineConfig {
    /// Takes ownership of every element in `stages`.
    /// wasm-bindgen cannot borrow class values nested in an array. To keep those handles,
    /// copy each retained element with `copyForTransfer()` before passing the array.
    #[allow(non_snake_case)]
    #[wasm_bindgen(constructor)]
    pub fn new(
        stages: Vec<WasmOcrPipelineStage>,
        qualityThresholds: &WasmOcrQualityThresholds,
    ) -> WasmOcrPipelineConfig {
        WasmOcrPipelineConfig {
            stages,
            quality_thresholds: qualityThresholds.clone(),
        }
    }

    #[wasm_bindgen]
    #[allow(clippy::should_implement_trait)]
    pub fn default() -> WasmOcrPipelineConfig {
        <WasmOcrPipelineConfig as ::core::default::Default>::default()
    }

    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmOcrPipelineConfig {
        self.clone()
    }

    /// Returns detached copies of the elements in `stages`.
    ///
    /// Changes to the returned values do not update this object. Modify the copies,
    /// then assign the array back to `stages`.
    #[wasm_bindgen(getter)]
    pub fn stages(&self) -> Vec<WasmOcrPipelineStage> {
        self.stages.clone()
    }

    /// Takes ownership of every element in `stages`.
    /// wasm-bindgen cannot borrow class values nested in an array; copy each retained
    /// element with `copyForTransfer()` before passing the array.
    #[wasm_bindgen(setter)]
    pub fn set_stages(&mut self, value: Vec<WasmOcrPipelineStage>) {
        self.stages = value;
    }

    /// Returns a detached copy of `qualityThresholds`.
    ///
    /// Changes to the returned value do not update this object. To update `qualityThresholds`,
    /// read it, modify the copy, then assign the copy back to `qualityThresholds`.
    #[wasm_bindgen(getter, js_name = "qualityThresholds")]
    pub fn quality_thresholds(&self) -> WasmOcrQualityThresholds {
        self.quality_thresholds.clone()
    }

    #[wasm_bindgen(setter, js_name = "qualityThresholds")]
    pub fn set_quality_thresholds(&mut self, value: &WasmOcrQualityThresholds) {
        self.quality_thresholds = value.clone();
    }
}

