/// Configuration for the redaction post-processor.
#[derive(Clone)]
#[wasm_bindgen]
pub struct WasmRedactionConfig {
    categories: JsValue,
    strategy: WasmRedactionStrategy,
    ner: Option<WasmNerConfig>,
    preserve_offsets: bool,
    custom_terms: Vec<WasmRedactionTerm>,
    custom_patterns: Vec<WasmRedactionPattern>,
    findings: Vec<WasmExternalRedactionFinding>,
    min_score: Option<f32>,
    findings_path: Option<String>,
    findings_offset_encoding: WasmRedactionOffsetEncoding,
}

impl Default for WasmRedactionConfig {
    fn default() -> Self {
        <xberg::RedactionConfig as Default>::default().into()
    }
}

#[wasm_bindgen]
impl WasmRedactionConfig {
    /// Takes ownership of `ner`.
    /// wasm-bindgen lowers a by-value class argument through `__destroy_into_raw()`, so each
    /// of those handles is dead once this returns. Passing a freshly built value is fine. To
    /// keep a handle you already hold, build with `default()` and assign the property instead:
    /// the generated setter borrows and leaves your handle alive.
    /// Takes ownership of every element in `customTerms`, `customPatterns`, `findings`.
    /// wasm-bindgen cannot borrow class values nested in an array. To keep those handles,
    /// copy each retained element with `copyForTransfer()` before passing the array.
    #[allow(clippy::too_many_arguments)]
    #[allow(non_snake_case)]
    #[wasm_bindgen(constructor)]
    pub fn new(
        categories: Option<JsValue>,
        strategy: Option<WasmRedactionStrategy>,
        preserveOffsets: Option<bool>,
        customTerms: Option<Vec<WasmRedactionTerm>>,
        customPatterns: Option<Vec<WasmRedactionPattern>>,
        findings: Option<Vec<WasmExternalRedactionFinding>>,
        findingsOffsetEncoding: Option<WasmRedactionOffsetEncoding>,
        ner: Option<WasmNerConfig>,
        minScore: Option<f32>,
        findingsPath: Option<String>,
    ) -> WasmRedactionConfig {
        let defaults = WasmRedactionConfig::default();
        WasmRedactionConfig {
            categories: categories.unwrap_or_default(),
            strategy: strategy.unwrap_or_else(|| {
                <xberg::RedactionConfig as ::core::default::Default>::default()
                    .strategy
                    .into()
            }),
            ner: ner.or(defaults.ner),
            preserve_offsets: preserveOffsets.unwrap_or(true),
            custom_terms: customTerms.unwrap_or_default(),
            custom_patterns: customPatterns.unwrap_or_default(),
            findings: findings.unwrap_or_default(),
            min_score: minScore.or(defaults.min_score),
            findings_path: findingsPath.or(defaults.findings_path),
            findings_offset_encoding: findingsOffsetEncoding.unwrap_or_else(|| {
                <xberg::RedactionConfig as ::core::default::Default>::default()
                    .findings_offset_encoding
                    .into()
            }),
        }
    }

    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmRedactionConfig {
        self.clone()
    }

    #[wasm_bindgen(getter)]
    pub fn categories(&self) -> JsValue {
        self.categories.clone()
    }

    #[wasm_bindgen(setter)]
    pub fn set_categories(&mut self, value: JsValue) {
        self.categories = value;
    }

    #[wasm_bindgen(getter)]
    pub fn strategy(&self) -> String {
        self.strategy.to_api_str().to_owned()
    }

    #[wasm_bindgen(setter)]
    pub fn set_strategy(&mut self, value: WasmRedactionStrategy) {
        self.strategy = value;
    }

    /// Returns a detached copy of `ner`.
    ///
    /// Changes to the returned value do not update this object. To update `ner`,
    /// read it, modify the copy, then assign the copy back to `ner`.
    #[wasm_bindgen(getter)]
    pub fn ner(&self) -> Option<WasmNerConfig> {
        self.ner.clone()
    }

    #[wasm_bindgen(setter)]
    pub fn set_ner(&mut self, value: &WasmNerConfig) {
        self.ner = Some(value.clone());
    }

    #[wasm_bindgen(js_name = "clearNer")]
    pub fn clear_ner(&mut self) {
        self.ner = None;
    }

    #[wasm_bindgen(getter, js_name = "preserveOffsets")]
    pub fn preserve_offsets(&self) -> bool {
        self.preserve_offsets
    }

    #[wasm_bindgen(setter, js_name = "preserveOffsets")]
    pub fn set_preserve_offsets(&mut self, value: bool) {
        self.preserve_offsets = value;
    }

    /// Returns detached copies of the elements in `customTerms`.
    ///
    /// Changes to the returned values do not update this object. Modify the copies,
    /// then assign the array back to `customTerms`.
    #[wasm_bindgen(getter, js_name = "customTerms")]
    pub fn custom_terms(&self) -> Vec<WasmRedactionTerm> {
        self.custom_terms.clone()
    }

    /// Takes ownership of every element in `customTerms`.
    /// wasm-bindgen cannot borrow class values nested in an array; copy each retained
    /// element with `copyForTransfer()` before passing the array.
    #[wasm_bindgen(setter, js_name = "customTerms")]
    pub fn set_custom_terms(&mut self, value: Vec<WasmRedactionTerm>) {
        self.custom_terms = value;
    }

    /// Returns detached copies of the elements in `customPatterns`.
    ///
    /// Changes to the returned values do not update this object. Modify the copies,
    /// then assign the array back to `customPatterns`.
    #[wasm_bindgen(getter, js_name = "customPatterns")]
    pub fn custom_patterns(&self) -> Vec<WasmRedactionPattern> {
        self.custom_patterns.clone()
    }

    /// Takes ownership of every element in `customPatterns`.
    /// wasm-bindgen cannot borrow class values nested in an array; copy each retained
    /// element with `copyForTransfer()` before passing the array.
    #[wasm_bindgen(setter, js_name = "customPatterns")]
    pub fn set_custom_patterns(&mut self, value: Vec<WasmRedactionPattern>) {
        self.custom_patterns = value;
    }

    /// Returns detached copies of the elements in `findings`.
    ///
    /// Changes to the returned values do not update this object. Modify the copies,
    /// then assign the array back to `findings`.
    #[wasm_bindgen(getter)]
    pub fn findings(&self) -> Vec<WasmExternalRedactionFinding> {
        self.findings.clone()
    }

    /// Takes ownership of every element in `findings`.
    /// wasm-bindgen cannot borrow class values nested in an array; copy each retained
    /// element with `copyForTransfer()` before passing the array.
    #[wasm_bindgen(setter)]
    pub fn set_findings(&mut self, value: Vec<WasmExternalRedactionFinding>) {
        self.findings = value;
    }

    #[wasm_bindgen(getter, js_name = "minScore")]
    pub fn min_score(&self) -> Option<f32> {
        self.min_score
    }

    #[wasm_bindgen(setter, js_name = "minScore")]
    pub fn set_min_score(&mut self, value: Option<f32>) {
        self.min_score = value;
    }

    #[wasm_bindgen(getter, js_name = "findingsPath")]
    pub fn findings_path(&self) -> Option<String> {
        self.findings_path.clone()
    }

    #[wasm_bindgen(setter, js_name = "findingsPath")]
    pub fn set_findings_path(&mut self, value: Option<String>) {
        self.findings_path = value;
    }

    #[wasm_bindgen(getter, js_name = "findingsOffsetEncoding")]
    pub fn findings_offset_encoding(&self) -> String {
        self.findings_offset_encoding.to_api_str().to_owned()
    }

    #[wasm_bindgen(setter, js_name = "findingsOffsetEncoding")]
    pub fn set_findings_offset_encoding(&mut self, value: WasmRedactionOffsetEncoding) {
        self.findings_offset_encoding = value;
    }

    #[allow(clippy::should_implement_trait)]
    #[wasm_bindgen]
    pub fn default() -> WasmRedactionConfig {
        xberg::RedactionConfig::default().into()
    }

    /// Validate user-supplied terms and patterns at config-construction time.
    ///
    /// Compiles every `RedactionPattern.pattern` (with the case-insensitive
    /// inline flag where applicable) and returns the first compilation error so
    /// the caller can reject the config before the redaction pipeline runs.
    /// Pure terms (regex-escaped) cannot fail to compile, but the function
    /// still rejects empty values to avoid degenerate zero-length matches.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen]
    pub fn validate(&self) -> Result<(), JsValue> {
        let result = xberg::RedactionConfig::from(self.clone())
            .validate()
            .map_err(|e| JsValue::from_str(&e.to_string()))?;
        Ok(result)
    }
}

