/// Sorted map of preset id → `Preset`.
#[derive(Clone)]
#[wasm_bindgen]
pub struct WasmRegistry {
    pub(crate) inner: Arc<std::sync::Mutex<xberg::Registry>>,
}

#[wasm_bindgen]
impl WasmRegistry {
    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmRegistry {
        self.clone()
    }

    /// Build the registry from preset files embedded at compile time under
    /// `src/presets/library/`. Validates every file against the meta-schema.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "loadEmbedded")]
    pub fn load_embedded() -> Result<WasmRegistry, JsValue> {
        let result = xberg::Registry::load_embedded().map_err(|e| JsValue::from_str(&e.to_string()))?;
        Ok(Self {
            inner: Arc::new(std::sync::Mutex::new(result)),
        })
    }

    /// Return the global registry, loading it on first access.
    ///
    /// # Panics
    ///
    /// Panics if any embedded preset is malformed. The build-time validation
    /// test ensures this cannot happen for the embedded presets; a panic here
    /// indicates a build artifact problem, not a runtime error.
    #[wasm_bindgen]
    pub fn global() -> WasmRegistry {
        Self {
            inner: Arc::new(std::sync::Mutex::new(xberg::Registry::global().clone())),
        }
    }

    /// Look up a preset by its identifier.
    #[wasm_bindgen]
    pub fn get(&self, id: String) -> Option<WasmPreset> {
        self.inner.lock().unwrap().get(&id).map(|v| v.clone().into())
    }

    /// Materialize a `PresetSummary` list for the public registry endpoint.
    #[wasm_bindgen]
    pub fn summaries(&self) -> Vec<WasmPresetSummary> {
        self.inner
            .lock()
            .unwrap()
            .summaries()
            .into_iter()
            .map(Into::into)
            .collect()
    }

    /// Number of presets currently loaded.
    #[wasm_bindgen]
    pub fn len(&self) -> usize {
        self.inner.lock().unwrap().len()
    }

    /// Whether the registry contains zero presets.
    #[wasm_bindgen(js_name = "isEmpty")]
    pub fn is_empty(&self) -> bool {
        self.inner.lock().unwrap().is_empty()
    }

    /// Read raw sample bytes for `<preset_id>` from
    /// `library/<id>/samples/<name>`. Returns `None` when the file is absent.
    #[wasm_bindgen(js_name = "sampleBytes")]
    pub fn sample_bytes(&self, preset_id: String, name: String) -> Option<Vec<u8>> {
        self.inner
            .lock()
            .unwrap()
            .sample_bytes(&preset_id, &name)
            .map(Into::into)
    }

    /// Load additional preset files from a runtime directory and insert them
    /// into this registry.
    ///
    /// Reads every `*.json` file directly under `dir` (non-recursive),
    /// validates each against the meta-schema, and inserts it. Files that fail
    /// validation are rejected — the error is returned immediately and the
    /// registry is left in a partially-updated state. Existing entries with the
    /// same id are overwritten.
    ///
    /// Returns the number of presets successfully loaded from `dir`.
    ///
    /// # Use case
    ///
    /// This is the injection point for downstream catalogs that add curated
    /// presets on top of the single embedded OSS preset.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "extendFromDir")]
    pub fn extend_from_dir(&self, dir: String) -> Result<usize, JsValue> {
        let result = self
            .inner
            .lock()
            .unwrap()
            .extend_from_dir(std::path::Path::new(&dir))
            .map_err(|e| JsValue::from_str(&e.to_string()))?;
        Ok(result)
    }
}

