/// The category of a downloaded asset.

#[wasm_bindgen]
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum WasmAssetCategory {
    Document = 0,
    Image = 1,
    Audio = 2,
    Video = 3,
    Font = 4,
    Stylesheet = 5,
    Script = 6,
    Archive = 7,
    Data = 8,
    Other = 9,
}

#[allow(clippy::derivable_impls)]
impl Default for WasmAssetCategory {
    fn default() -> Self {
        Self::Image
    }
}

impl WasmAssetCategory {
    /// Returns the serde wire string for this variant (e.g. `"stop"`, `"tool_calls"`).
    pub fn to_api_str(self) -> &'static str {
        match self {
            Self::Document => "document",
            Self::Image => "image",
            Self::Audio => "audio",
            Self::Video => "video",
            Self::Font => "font",
            Self::Stylesheet => "stylesheet",
            Self::Script => "script",
            Self::Archive => "archive",
            Self::Data => "data",
            Self::Other => "other",
        }
    }

    /// Parses a serde wire string and returns the corresponding variant, or None if unrecognized.
    pub fn from_api_str(s: &str) -> Option<Self> {
        match s {
            "document" => Some(Self::Document),
            "image" => Some(Self::Image),
            "audio" => Some(Self::Audio),
            "video" => Some(Self::Video),
            "font" => Some(Self::Font),
            "stylesheet" => Some(Self::Stylesheet),
            "script" => Some(Self::Script),
            "archive" => Some(Self::Archive),
            "data" => Some(Self::Data),
            "other" => Some(Self::Other),
            _ => None,
        }
    }
}

