/// Traversal order for a crawl.
///
/// Selects both the queue discipline and the selection strategy, because global order is a
/// property of the frontier: the engine hands its bounded selection window to the strategy, so
/// a strategy alone can only reorder URLs that have already been dequeued.

#[wasm_bindgen]
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum WasmCrawlStrategyKind {
    Bfs = 0,
    Dfs = 1,
    BestFirst = 2,
    Adaptive = 3,
}

#[allow(clippy::derivable_impls)]
impl Default for WasmCrawlStrategyKind {
    fn default() -> Self {
        Self::Bfs
    }
}

impl WasmCrawlStrategyKind {
    /// Returns the serde wire string for this variant (e.g. `"stop"`, `"tool_calls"`).
    pub fn to_api_str(self) -> &'static str {
        match self {
            Self::Bfs => "bfs",
            Self::Dfs => "dfs",
            Self::BestFirst => "best_first",
            Self::Adaptive => "adaptive",
        }
    }

    /// Parses a serde wire string and returns the corresponding variant, or None if unrecognized.
    pub fn from_api_str(s: &str) -> Option<Self> {
        match s {
            "bfs" => Some(Self::Bfs),
            "dfs" => Some(Self::Dfs),
            "best_first" => Some(Self::BestFirst),
            "adaptive" => Some(Self::Adaptive),
            _ => None,
        }
    }
}

