/// Extract content from a single bytes or URI input.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen]
pub async fn extract(
    input: Option<WasmExtractInput>,
    config: Option<WasmExtractionConfig>,
) -> Result<WasmExtractionResult, JsValue> {
    let input_core: xberg::ExtractInput = input.map(Into::into).unwrap_or_default();
    let config_core: xberg::ExtractionConfig = config.map(Into::into).unwrap_or_default();
    let result = xberg::extract(input_core, &config_core)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(result.into())
}

/// Extract content from multiple bytes or URI inputs.
