pub async fn extract_batch(
    inputs: Vec<WasmExtractInput>,
    config: Option<WasmExtractionConfig>,
) -> Result<WasmExtractionResult, JsValue> {
    let inputs_core: Vec<xberg::ExtractInput> = inputs.into_iter().map(Into::into).collect();
    let config_core: xberg::ExtractionConfig = config.map(Into::into).unwrap_or_default();
    let result = xberg::extract_batch(inputs_core, &config_core)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(result.into())
}

