#[cfg(feature = "redaction")]
/// Redact an owned document using a JSON array or JSON Lines payload from an external inspection engine.
///
/// The payload is parsed in Rust so vendor aliases and nested fields remain intact across language bindings.
/// `offset_encoding` defaults to `unicode_code_points` and `max_findings` defaults to 10,000 when omitted.
/// Unknown encodings return a validation error.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen(js_name = "redactExternal")]
pub async fn redact_external(
    document: Option<WasmExtractedDocument>,
    config: Option<WasmRedactionConfig>,
    findings_json: String,
    offset_encoding: Option<String>,
    max_findings: Option<u32>,
) -> Result<WasmExtractedDocument, JsValue> {
    let document_core: xberg::ExtractedDocument = document.map(Into::into).unwrap_or_default();
    let config_core: xberg::RedactionConfig = config.map(Into::into).unwrap_or_default();
    let result = xberg::redact_external(
        document_core,
        config_core,
        &findings_json,
        offset_encoding.as_deref(),
        max_findings,
    )
    .await
    .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(result.into())
}

