impl From<WasmRerankerModelType> for xberg::RerankerModelType {
    fn from(val: WasmRerankerModelType) -> Self {
        match val.r#type.as_str() {
            "preset" => Self::Preset {
                name: val.name.clone().unwrap_or_default(),
            },
            "custom" => Self::Custom {
                model_id: val.model_id.clone().unwrap_or_default(),
                model_file: val.model_file.clone(),
                additional_files: val.additional_files.clone().unwrap_or_default(),
                max_length: val.max_length.clone(),
                head: val
                    .head
                    .clone()
                    .map(Into::into)
                    .unwrap_or_else(|| wasm_bindgen::throw_str("missing enum field head")),
            },
            "llm" => Self::Llm {
                llm: val
                    .llm
                    .clone()
                    .map(Into::into)
                    .map(Box::new)
                    .unwrap_or_else(|| wasm_bindgen::throw_str("missing enum field llm")),
            },
            "plugin" => Self::Plugin {
                name: val.name.clone().unwrap_or_default(),
            },
            _ => Self::Preset {
                name: Default::default(),
            },
        }
    }
}

impl From<xberg::RerankerModelType> for WasmRerankerModelType {
    fn from(val: xberg::RerankerModelType) -> Self {
        match val {
            xberg::RerankerModelType::Preset { name } => Self {
                r#type: "preset".to_string(),
                additional_files: None,
                head: None,
                llm: None,
                max_length: None,
                model_file: None,
                model_id: None,
                name: Some(name),
            },
            xberg::RerankerModelType::Custom {
                model_id,
                model_file,
                additional_files,
                max_length,
                head,
            } => Self {
                r#type: "custom".to_string(),
                additional_files: Some(additional_files),
                head: Some(head.into()),
                llm: None,
                max_length,
                model_file,
                model_id: Some(model_id),
                name: None,
            },
            xberg::RerankerModelType::Llm { llm } => Self {
                r#type: "llm".to_string(),
                additional_files: None,
                head: None,
                llm: Some((*llm).into()),
                max_length: None,
                model_file: None,
                model_id: None,
                name: None,
            },
            xberg::RerankerModelType::Plugin { name } => Self {
                r#type: "plugin".to_string(),
                additional_files: None,
                head: None,
                llm: None,
                max_length: None,
                model_file: None,
                model_id: None,
                name: Some(name),
            },
            _ => Self::default(),
        }
    }
}

